solution.solution.py:
import struct

LAYOUT = struct.Struct("<I8sB")


def pack_record(id, name, score):
    encoded = name.encode("utf-8")
    if len(encoded) > 8:
        raise ValueError("name too long")
    if not 0 <= score <= 255:
        raise ValueError("score out of range")
    return LAYOUT.pack(id, encoded, score)


def unpack_record(data):
    id, raw, score = LAYOUT.unpack(data)
    return (id, raw.rstrip(b"\0").decode("utf-8"), score)

unitTests:
@test("the layout")
def _():
    check_eq(pack_record(1, "Ada", 91).hex(" "), "01 00 00 00 41 64 61 00 00 00 00 00 5b")

@test("round trip")
def _():
    for rec in [(1, "Ada", 91), (4000000000, "Zoë", 0), (7, "eightchr", 255)]:
        check_eq(unpack_record(pack_record(*rec)), rec)

@test("too long or too big refused")
def _():
    check_raises(ValueError, pack_record, 1, "ninechars", 1)
    check_raises(ValueError, pack_record, 1, "Ada", 256)

